-- ============================================================================
-- REFERENSI AKUN BELANJA & REKENING SIPD RI
-- SIPA (Sistem Informasi Pengelolaan Aset) - BPKAD Kabupaten Tapin
-- Sumber Data: sipd_ri_r_akun.xlsx
-- ============================================================================

SET FOREIGN_KEY_CHECKS = 0;

-- 1. Tabel Utama: ref_akun_belanja (Khusus Rekening Belanja 5.x)
CREATE TABLE IF NOT EXISTS `ref_akun_belanja` (
  `id` INT(10) UNSIGNED NOT NULL AUTO_INCREMENT,
  `kode_akun` VARCHAR(50) NOT NULL COMMENT 'Kode Rekening Belanja SIPD RI',
  `nama_akun` VARCHAR(500) NOT NULL COMMENT 'Uraian Rekening Belanja',
  `kelompok` VARCHAR(100) NOT NULL DEFAULT 'Belanja Operasi',
  `level` TINYINT(2) UNSIGNED NOT NULL DEFAULT 6 COMMENT 'Level rekening: 1=Akun s/d 6=Sub Rincian',
  `is_leaf` TINYINT(1) NOT NULL DEFAULT 1 COMMENT '1=Sub Rincian/Dapat dianggarkan, 0=Header',
  `is_active` TINYINT(1) NOT NULL DEFAULT 1,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_kode_akun_belanja` (`kode_akun`),
  KEY `idx_kelompok` (`kelompok`),
  KEY `idx_level` (`level`),
  KEY `idx_is_leaf` (`is_leaf`),
  FULLTEXT KEY `ft_nama_akun` (`nama_akun`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 2. View Alias: akun_belanja
CREATE OR REPLACE VIEW `akun_belanja` AS SELECT * FROM `ref_akun_belanja`;

-- 3. Tabel Lengkap Seluruh Rekening SIPD RI (ref_akun)
CREATE TABLE IF NOT EXISTS `ref_akun` (
  `id` INT(10) UNSIGNED NOT NULL AUTO_INCREMENT,
  `kode_akun` VARCHAR(50) NOT NULL COMMENT 'Kode Rekening SIPD RI',
  `nama_akun` VARCHAR(500) NOT NULL COMMENT 'Uraian Rekening',
  `tipe_akun` ENUM('Pendapatan','Belanja','Pembiayaan','Lainnya') NOT NULL DEFAULT 'Belanja',
  `kelompok` VARCHAR(100) DEFAULT NULL,
  `level` TINYINT(2) UNSIGNED NOT NULL DEFAULT 6,
  `is_leaf` TINYINT(1) NOT NULL DEFAULT 1,
  `is_belanja` TINYINT(1) NOT NULL DEFAULT 0,
  `is_active` TINYINT(1) NOT NULL DEFAULT 1,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_ref_kode_akun` (`kode_akun`),
  KEY `idx_tipe_akun` (`tipe_akun`),
  KEY `idx_is_belanja` (`is_belanja`),
  KEY `idx_level` (`level`),
  KEY `idx_is_leaf` (`is_leaf`),
  FULLTEXT KEY `ft_ref_nama_akun` (`nama_akun`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 4. Data ref_akun_belanja
